mapper.select:
select lot_id, device_name, sum(seed_count) as seed_count, ROUND(sum(worked_area), 2) as worked_area, -- 保留两位小数 sum(sow_line) as sow_line, sum(sow_distance) as sow_distance, count(*) as sow_count, case when sum(worked_area) > 0 then sum(seed_count) * 15.0 / sum(worked_area) else 0 end as seed_count_hectare from data_message_day desm
and desm.year_string = #{query.yearString}
and desm.month_string = #{query.monthString}
and desm.day_string = #{query.dayString}
and desm.seed_count != 0
group by lot_id, device_name
